SELECT emp.id, emp.job_title AS employee_job_title, emp.hire_date AS employee_hire_date, emp.manager_id AS employee_manager_id, mgr.hire_date AS manager_hire_date, mgr.email AS manager_email, mgr.level AS manager_level FROM employees emp LEFT JOIN employees mgr ON emp.manager_id = mgr.id WHERE mgr.level NOT IN ('L5', 'L1', 'L3') AND UPPER(mgr.email) LIKE '%ARO%' ORDER BY emp.id DESC LIMIT 50
